/**
 * FamilyPulse database schema (PostgreSQL). Documented in docs/DATABASE_SCHEMA.md.
 *
 * Conventions
 *  - UUID primary keys generated by the application.
 *  - Money: bigint integer cents (never floating point). Percentages: integer basis points.
 *  - Calendar dates: `date` columns exchanged as "YYYY-MM-DD" strings.
 *  - Every household-owned row carries household_id so ownership can be enforced in one predicate.
 */
import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import type { NotificationPrefs } from '@familypulse/shared';

const money = (name: string) => bigint(name, { mode: 'number' });
const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => ts('created_at').notNull().defaultNow();
const updatedAt = () => ts('updated_at').notNull().defaultNow();

// ---------------------------------------------------------------- identity
export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    email: text('email').notNull(),
    name: text('name').notNull(),
    passwordHash: text('password_hash').notNull(),
    notificationPrefs: jsonb('notification_prefs').$type<Partial<NotificationPrefs>>().notNull().default({}),
    lastHouseholdId: uuid('last_household_id'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('users_email_key').on(sql`lower(${t.email})`)],
);

export const sessions = pgTable(
  'sessions',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** SHA-256 of the random session token; the raw token only ever lives in the cookie. */
    tokenHash: text('token_hash').notNull(),
    userAgent: text('user_agent'),
    createdAt: createdAt(),
    lastSeenAt: ts('last_seen_at').notNull().defaultNow(),
    expiresAt: ts('expires_at').notNull(),
  },
  (t) => [uniqueIndex('sessions_token_hash_key').on(t.tokenHash), index('sessions_user_idx').on(t.userId)],
);

export const passwordResetTokens = pgTable(
  'password_reset_tokens',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull(),
    expiresAt: ts('expires_at').notNull(),
    usedAt: ts('used_at'),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('password_reset_token_hash_key').on(t.tokenHash), index('password_reset_user_idx').on(t.userId)],
);

// ---------------------------------------------------------------- households & roles
export const households = pgTable('households', {
  id: uuid('id').primaryKey(),
  name: text('name').notNull(),
  currency: text('currency').notNull().default('USD'),
  /** True for the demo household created by the seed script — surfaced in the UI as "Sample data". */
  isSample: boolean('is_sample').notNull().default(false),
  onboardedAt: ts('onboarded_at'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const householdMembers = pgTable(
  'household_members',
  {
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: text('role', { enum: ['owner', 'admin', 'contributor', 'viewer'] }).notNull(),
    joinedAt: ts('joined_at').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.householdId, t.userId] }),
    index('household_members_user_idx').on(t.userId),
    check('household_members_role_check', sql`${t.role} in ('owner','admin','contributor','viewer')`),
    // Exactly one owner per household.
    uniqueIndex('household_one_owner').on(t.householdId).where(sql`${t.role} = 'owner'`),
  ],
);

export const categories = pgTable(
  'categories',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    group: text('group', { enum: ['living', 'entertainment', 'unexpected', 'income'] }).notNull(),
    color: text('color').notNull(),
    archivedAt: ts('archived_at'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('categories_household_name_key').on(t.householdId, sql`lower(${t.name})`),
    index('categories_household_idx').on(t.householdId),
    check('categories_group_check', sql`${t.group} in ('living','entertainment','unexpected','income')`),
  ],
);

/** Contributors can be limited to editing entries in specific categories (paper §2.6). */
export const memberCategoryScopes = pgTable(
  'member_category_scopes',
  {
    householdId: uuid('household_id').notNull(),
    userId: uuid('user_id').notNull(),
    categoryId: uuid('category_id')
      .notNull()
      .references(() => categories.id, { onDelete: 'cascade' }),
  },
  (t) => [
    primaryKey({ columns: [t.householdId, t.userId, t.categoryId] }),
    foreignKey({
      columns: [t.householdId, t.userId],
      foreignColumns: [householdMembers.householdId, householdMembers.userId],
      name: 'member_scope_member_fk',
    }).onDelete('cascade'),
  ],
);

export const invitations = pgTable(
  'invitations',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    email: text('email'),
    role: text('role', { enum: ['admin', 'contributor', 'viewer'] }).notNull(),
    categoryScope: jsonb('category_scope').$type<string[]>().notNull().default([]),
    tokenHash: text('token_hash').notNull(),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    expiresAt: ts('expires_at').notNull(),
    acceptedAt: ts('accepted_at'),
    acceptedBy: uuid('accepted_by').references(() => users.id, { onDelete: 'set null' }),
    revokedAt: ts('revoked_at'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('invitations_token_hash_key').on(t.tokenHash),
    index('invitations_household_idx').on(t.householdId),
    check('invitations_role_check', sql`${t.role} in ('admin','contributor','viewer')`),
  ],
);

// ---------------------------------------------------------------- accounts & ledger
export const accounts = pgTable(
  'accounts',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    ownerUserId: uuid('owner_user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'restrict' }),
    name: text('name').notNull(),
    type: text('type', {
      enum: ['checking', 'savings', 'cash', 'credit_card', 'loan', 'investment', 'other_asset'],
    }).notNull(),
    visibility: text('visibility', { enum: ['shared', 'private'] }).notNull().default('shared'),
    institution: text('institution'),
    last4: text('last4'),
    openingBalanceCents: money('opening_balance_cents').notNull().default(0),
    openingDate: date('opening_date', { mode: 'string' }).notNull(),
    creditLimitCents: money('credit_limit_cents'),
    /** Data source: 'manual' entry or 'csv' import. Bank aggregation providers would add values here. */
    provider: text('provider', { enum: ['manual', 'csv'] })
      .notNull()
      .default('manual'),
    archivedAt: ts('archived_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('accounts_household_idx').on(t.householdId),
    check(
      'accounts_type_check',
      sql`${t.type} in ('checking','savings','cash','credit_card','loan','investment','other_asset')`,
    ),
    check('accounts_visibility_check', sql`${t.visibility} in ('shared','private')`),
    check('accounts_last4_check', sql`${t.last4} is null or ${t.last4} ~ '^[0-9]{4}$'`),
  ],
);

export const recurringItems = pgTable(
  'recurring_items',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    kind: text('kind', { enum: ['income', 'bill'] }).notNull(),
    label: text('label').notNull(),
    amountCents: money('amount_cents').notNull(),
    minAmountCents: money('min_amount_cents'),
    frequency: text('frequency', {
      enum: ['weekly', 'biweekly', 'semimonthly', 'monthly', 'quarterly', 'yearly', 'once'],
    }).notNull(),
    /** Day-of-month the schedule is anchored to (so Jan 31 → Feb 28 → Mar 31). */
    anchorDay: integer('anchor_day').notNull(),
    nextDate: date('next_date', { mode: 'string' }).notNull(),
    endDate: date('end_date', { mode: 'string' }),
    accountId: uuid('account_id').references(() => accounts.id, { onDelete: 'set null' }),
    categoryId: uuid('category_id').references(() => categories.id, { onDelete: 'set null' }),
    autopay: boolean('autopay').notNull().default(false),
    active: boolean('active').notNull().default(true),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('recurring_household_idx').on(t.householdId, t.nextDate),
    check('recurring_amount_positive', sql`${t.amountCents} > 0`),
    check('recurring_kind_check', sql`${t.kind} in ('income','bill')`),
    check('recurring_anchor_day_check', sql`${t.anchorDay} between 1 and 31`),
  ],
);

export const transactions = pgTable(
  'transactions',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    accountId: uuid('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    type: text('type', { enum: ['expense', 'income', 'transfer', 'adjustment'] }).notNull(),
    /** Signed from the account's point of view: outflow < 0, inflow > 0. */
    amountCents: money('amount_cents').notNull(),
    date: date('date', { mode: 'string' }).notNull(),
    description: text('description').notNull(),
    merchant: text('merchant'),
    categoryId: uuid('category_id').references(() => categories.id, { onDelete: 'set null' }),
    notes: text('notes'),
    transferGroupId: uuid('transfer_group_id'),
    source: text('source', { enum: ['manual', 'import', 'recurring', 'adjustment', 'transfer'] })
      .notNull()
      .default('manual'),
    recurringId: uuid('recurring_id').references(() => recurringItems.id, { onDelete: 'set null' }),
    /** Optimistic-concurrency version; increments on every edit. */
    version: integer('version').notNull().default(1),
    clientRequestId: uuid('client_request_id'),
    importHash: text('import_hash'),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    updatedBy: uuid('updated_by').references(() => users.id, { onDelete: 'set null' }),
    deletedAt: ts('deleted_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('transactions_household_date_idx').on(t.householdId, t.date),
    index('transactions_account_date_idx').on(t.accountId, t.date),
    index('transactions_category_idx').on(t.categoryId),
    index('transactions_transfer_group_idx').on(t.transferGroupId),
    uniqueIndex('transactions_client_request_key')
      .on(t.householdId, t.clientRequestId)
      .where(sql`${t.clientRequestId} is not null`),
    uniqueIndex('transactions_import_hash_key')
      .on(t.accountId, t.importHash)
      .where(sql`${t.importHash} is not null and ${t.deletedAt} is null`),
    check('transactions_type_check', sql`${t.type} in ('expense','income','transfer','adjustment')`),
    check(
      'transactions_sign_check',
      sql`(${t.type} = 'expense' and ${t.amountCents} < 0) or (${t.type} = 'income' and ${t.amountCents} > 0) or (${t.type} in ('transfer','adjustment') and ${t.amountCents} <> 0)`,
    ),
  ],
);

export const transactionTags = pgTable(
  'transaction_tags',
  {
    transactionId: uuid('transaction_id')
      .notNull()
      .references(() => transactions.id, { onDelete: 'cascade' }),
    tag: text('tag').notNull(),
  },
  (t) => [primaryKey({ columns: [t.transactionId, t.tag] }), index('transaction_tags_tag_idx').on(t.tag)],
);

export type TransactionSnapshot = {
  type: string;
  accountId: string;
  amountCents: number;
  date: string;
  description: string;
  merchant: string | null;
  categoryId: string | null;
  notes: string | null;
  tags: string[];
  deleted?: boolean;
};

/** Immutable, time-stamped change log for every ledger entry (paper §2.6 "version-controlled"). */
export const transactionRevisions = pgTable(
  'transaction_revisions',
  {
    id: uuid('id').primaryKey(),
    transactionId: uuid('transaction_id')
      .notNull()
      .references(() => transactions.id, { onDelete: 'cascade' }),
    version: integer('version').notNull(),
    action: text('action', { enum: ['created', 'updated', 'reverted', 'deleted', 'restored'] }).notNull(),
    snapshot: jsonb('snapshot').$type<TransactionSnapshot>().notNull(),
    changes: jsonb('changes').$type<{ field: string; from: unknown; to: unknown }[]>().notNull().default([]),
    editorId: uuid('editor_id').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('transaction_revisions_version_key').on(t.transactionId, t.version)],
);

export const transactionComments = pgTable(
  'transaction_comments',
  {
    id: uuid('id').primaryKey(),
    transactionId: uuid('transaction_id')
      .notNull()
      .references(() => transactions.id, { onDelete: 'cascade' }),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    authorId: uuid('author_id').references(() => users.id, { onDelete: 'set null' }),
    body: text('body').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('transaction_comments_txn_idx').on(t.transactionId, t.createdAt)],
);

export const commentMentions = pgTable(
  'comment_mentions',
  {
    commentId: uuid('comment_id')
      .notNull()
      .references(() => transactionComments.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
  },
  (t) => [primaryKey({ columns: [t.commentId, t.userId] })],
);

export const attachments = pgTable(
  'attachments',
  {
    id: uuid('id').primaryKey(),
    transactionId: uuid('transaction_id')
      .notNull()
      .references(() => transactions.id, { onDelete: 'cascade' }),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    filename: text('filename').notNull(),
    mimeType: text('mime_type').notNull(),
    sizeBytes: integer('size_bytes').notNull(),
    storageKey: text('storage_key').notNull(),
    uploadedBy: uuid('uploaded_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [index('attachments_txn_idx').on(t.transactionId)],
);

// ---------------------------------------------------------------- budgets & goals
/** A plan takes effect from `month` and carries forward until a later plan exists. */
export const budgetPlans = pgTable(
  'budget_plans',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    month: text('month').notNull(),
    expectedIncomeCents: money('expected_income_cents').notNull().default(0),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('budget_plans_household_month_key').on(t.householdId, t.month),
    check('budget_plans_month_check', sql`${t.month} ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'`),
  ],
);

export const budgetItems = pgTable(
  'budget_items',
  {
    planId: uuid('plan_id')
      .notNull()
      .references(() => budgetPlans.id, { onDelete: 'cascade' }),
    categoryId: uuid('category_id')
      .notNull()
      .references(() => categories.id, { onDelete: 'cascade' }),
    amountCents: money('amount_cents').notNull(),
  },
  (t) => [primaryKey({ columns: [t.planId, t.categoryId] }), check('budget_items_amount_check', sql`${t.amountCents} >= 0`)],
);

export const goals = pgTable(
  'goals',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    icon: text('icon').notNull().default('other'),
    targetCents: money('target_cents').notNull(),
    targetDate: date('target_date', { mode: 'string' }),
    plannedMonthlyCents: money('planned_monthly_cents').notNull().default(0),
    reachedAt: ts('reached_at'),
    archivedAt: ts('archived_at'),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('goals_household_idx').on(t.householdId), check('goals_target_positive', sql`${t.targetCents} > 0`)],
);

export const rules = pgTable(
  'rules',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    enabled: boolean('enabled').notNull().default(true),
    conditions: jsonb('conditions').$type<Record<string, unknown>>().notNull(),
    actions: jsonb('actions').$type<Record<string, unknown>>().notNull(),
    priority: integer('priority').notNull().default(0),
    timesApplied: integer('times_applied').notNull().default(0),
    lastAppliedAt: ts('last_applied_at'),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('rules_household_idx').on(t.householdId)],
);

export const goalContributions = pgTable(
  'goal_contributions',
  {
    id: uuid('id').primaryKey(),
    goalId: uuid('goal_id')
      .notNull()
      .references(() => goals.id, { onDelete: 'cascade' }),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    amountCents: money('amount_cents').notNull(),
    date: date('date', { mode: 'string' }).notNull(),
    note: text('note'),
    transactionId: uuid('transaction_id').references(() => transactions.id, { onDelete: 'set null' }),
    ruleId: uuid('rule_id').references(() => rules.id, { onDelete: 'set null' }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [
    index('goal_contributions_goal_idx').on(t.goalId, t.date),
    check('goal_contributions_nonzero', sql`${t.amountCents} <> 0`),
  ],
);

// ---------------------------------------------------------------- planning
export const scenarios = pgTable(
  'scenarios',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    description: text('description'),
    horizonMonths: integer('horizon_months').notNull(),
    granularity: text('granularity', { enum: ['week', 'month'] }).notNull(),
    incomeMode: text('income_mode', { enum: ['expected', 'conservative'] }).notNull(),
    adjustments: jsonb('adjustments').$type<unknown[]>().notNull(),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('scenarios_household_idx').on(t.householdId)],
);

// ---------------------------------------------------------------- notifications & activity
export const notifications = pgTable(
  'notifications',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    householdId: uuid('household_id').references(() => households.id, { onDelete: 'cascade' }),
    type: text('type').notNull(),
    title: text('title').notNull(),
    body: text('body').notNull(),
    link: text('link'),
    /** Prevents the alert engine from sending the same alert twice. */
    dedupeKey: text('dedupe_key'),
    readAt: ts('read_at'),
    createdAt: createdAt(),
  },
  (t) => [
    index('notifications_user_idx').on(t.userId, t.createdAt),
    uniqueIndex('notifications_dedupe_key').on(t.userId, t.dedupeKey).where(sql`${t.dedupeKey} is not null`),
  ],
);

export const activityEvents = pgTable(
  'activity_events',
  {
    id: uuid('id').primaryKey(),
    householdId: uuid('household_id')
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    actorId: uuid('actor_id').references(() => users.id, { onDelete: 'set null' }),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id'),
    action: text('action').notNull(),
    summary: text('summary').notNull(),
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    /** Events about private accounts are visible only to this user. */
    visibleToUserId: uuid('visible_to_user_id').references(() => users.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [index('activity_household_idx').on(t.householdId, t.createdAt)],
);
